export type CopyStatus = 'idle' | 'copied' | 'error';

export type CopyToClipboardOptions = {
	timeout?: number;
	onCopy?: (value: string) => void;
	onError?: (reason: unknown) => void;
};

export class CopyToClipboardState {
	#read: () => CopyToClipboardOptions;

	#status = $state<CopyStatus>('idle');
	#timer: ReturnType<typeof setTimeout> | undefined;

	constructor(options: CopyToClipboardOptions | (() => CopyToClipboardOptions) = {}) {
		this.#read = typeof options === 'function' ? options : () => options;

		$effect(() => () => clearTimeout(this.#timer));
	}

	get status() {
		return this.#status;
	}

	get copied() {
		return this.#status === 'copied';
	}

	reset = () => {
		clearTimeout(this.#timer);
		this.#status = 'idle';
	};

	copy = async (value: string) => {
		if (!value) return;

		let ok: boolean;
		let reason: unknown = null;

		try {
			if (navigator.clipboard?.writeText) {
				await navigator.clipboard.writeText(value);
				ok = true;
			} else {
				ok = writeFallback(value);
			}
		} catch (error) {
			reason = error;
			try {
				ok = writeFallback(value);
			} catch {
				ok = false;
			}
		}

		this.#status = ok ? 'copied' : 'error';
		if (ok) this.#read().onCopy?.(value);
		else this.#read().onError?.(reason);

		clearTimeout(this.#timer);
		this.#timer = setTimeout(() => (this.#status = 'idle'), this.#read().timeout ?? 2000);
	};
}

function writeFallback(text: string): boolean {
	const area = document.createElement('textarea');
	area.value = text;
	area.setAttribute('readonly', '');
	area.style.cssText = 'position:fixed;top:0;left:0;opacity:0';
	document.body.appendChild(area);

	const selection = document.getSelection();
	const previous = selection && selection.rangeCount > 0 ? selection.getRangeAt(0) : null;

	area.select();
	let ok: boolean;
	try {
		ok = document.execCommand('copy');
	} catch {
		ok = false;
	}

	document.body.removeChild(area);
	if (selection && previous) {
		selection.removeAllRanges();
		selection.addRange(previous);
	}
	return ok;
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge class values, resolving Tailwind conflicts so the last one wins.
 *
 * This is what makes the `class` prop on every component behave the way the
 * registry documents it: "appended last to the root, so width and spacing are
 * the caller's". Plain concatenation would leave both `p-2` and the caller's
 * `p-4` in the list and let source order in the stylesheet decide; `twMerge`
 * drops the loser outright.
 *
 * Design-language classes from `layout.css` (`mat-panel`, `press`, `tnum`, …)
 * are not utilities, so `twMerge` passes them through untouched.
 */
export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
